	/** 
	 * jumpstart the process by instantiating2 Aircraft
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		aircraftId = AircraftService.getAircraftInstance()
		.createAircraft( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		AircraftService.getAircraftInstance()
				.createAircraft( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.aircraftSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Aircraft : " + successValue.getAircraftId());
							  if (successValue.getAircraftId().equals(aircraftId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfAircraftList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Aircraft test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on aircraft consumed")
					);
			subscriber.aircraftSubscribe( aircraftId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Aircraft : " + successValue.getAircraftId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfAircraftList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on aircraft for aircraftId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Aircraft. 
	 */
	protected Aircraft read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Aircraft" );

		Aircraft entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Aircraft with primary key" );
		msg.append( aircraftId );
		
		AircraftFetchOneSummary fetchOneSummary = new AircraftFetchOneSummary( aircraftId );

		try {
			entity = AircraftService.getAircraftInstance().getAircraft( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Aircraft " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Aircraft.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Aircraft." );

		StringBuilder msg = new StringBuilder( "Failed to update a Aircraft : " );        
		Aircraft entity = read();
		UpdateAircraftCommand command = generateUpdateCommand();
		command.setAircraftId(entity.getAircraftId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Aircraft." );

			// for use later on...
			aircraftId = entity.getAircraftId();

			AircraftService proxy = AircraftService.getAircraftInstance();  

			proxy.updateAircraft( command ).get();

			LOGGER.info( "-- Successfully saved Aircraft - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + aircraftId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Aircraft.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Aircraft." );

		Aircraft entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Aircraft with id " + aircraftId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Aircraft with id " + aircraftId );

			throw e;
		}

		try{
			AircraftService.getAircraftInstance().delete( new DeleteAircraftCommand( entity.getAircraftId() ) ).get();
			LOGGER.info( "-- Successfully deleted Aircraft with id " + aircraftId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Aircraft with id " + aircraftId );

			throw e;
		}
	}

	/**
	 * get all Aircrafts.
	 */
	protected List<Aircraft> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Aircrafts:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Aircraft : " );        
		List<Aircraft> collection  = new ArrayList<>();

		try {
			// call the static get method on the AircraftService
			collection = AircraftService.getAircraftInstance().getAllAircraft();
			assertNotNull( collection, "An Empty collection of Aircraft was incorrectly returned.");
			
			// Now print out the values
			Aircraft entity = null;            
			Iterator<Aircraft> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getAircraftId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

